// After Shiny.bindAll, some JS-heavy inputs (colourpicker, sliderInput)
// need an extra nudge to initialize their widget UI on dynamically added DOM.
const initSpecialInputs = (row) => {
  // colourpicker: if the binding didn't fully initialize, manually trigger
  // spectrum on any .shiny-colour-input that lacks a .sp-replacer sibling.
  row.querySelectorAll(".shiny-colour-input").forEach((input) => {
    if (input.parentNode && !input.parentNode.querySelector(".sp-replacer")) {
      // Re-trigger colourpicker's initialization via jQuery if available
      if (typeof $ !== "undefined" && $.fn && $.fn.spectrum) {
        const initVal = input.dataset.initValue || input.value || "#000000";
        const palette = input.dataset.palette || "square";
        const showColour = input.dataset.showColour || "both";
        $(input).spectrum({
          color: initVal,
          showInput: true,
          showInitial: true,
          showPalette: (palette !== "limited"),
          showAlpha: input.dataset.allowTransparent === "true",
          preferredFormat: "hex",
          allowEmpty: input.dataset.allowEmpty === "true",
          flat: false,
          change: function (color) {
            input.value = color ? color.toHexString() : "";
            $(input).trigger("change");
          },
          move: function (color) {
            input.value = color ? color.toHexString() : "";
            $(input).trigger("change");
          }
        });
        // Show the colour beside the input based on showColour setting
        const replacer = input.parentNode.querySelector(".sp-replacer");
        if (replacer) {
          if (showColour === "background" || showColour === "both") {
            replacer.style.display = "";
          }
          if (showColour === "text" || showColour === "both") {
            $(input).show();
          } else {
            $(input).hide();
          }
        }
      }
    }
  });
};

